"""Offline reviewed table DDL; migration copies literals, never imports this."""

TABLE_SQL = "\nCREATE TABLE factor_execution_snapshot_publications (\n\tid UUID NOT NULL, \n\tevaluation_id UUID NOT NULL, \n\tsource_id UUID NOT NULL, \n\tstart_id UUID NOT NULL, \n\tfactor_version_id UUID NOT NULL, \n\treservation_id UUID NOT NULL, \n\tmanifest JSONB NOT NULL, \n\tmanifest_sha256 VARCHAR(64) NOT NULL, \n\tmanifest_object_id UUID NOT NULL, \n\tmanifest_size_bytes BIGINT NOT NULL, \n\tmanifest_storage_key VARCHAR(300) NOT NULL, \n\tjournal JSONB NOT NULL, \n\tjournal_sha256 VARCHAR(64) NOT NULL, \n\tjournal_key VARCHAR(300) NOT NULL, \n\tpeak_bytes BIGINT NOT NULL, \n\tpeak_entries INTEGER NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\towner_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tattempt_id UUID NOT NULL, \n\tgeneration INTEGER NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (owner_id, run_id, attempt_id, generation, id), \n\tUNIQUE (owner_id, id), \n\tUNIQUE (evaluation_id), \n\tUNIQUE (reservation_id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, evaluation_id, start_id, source_id, factor_version_id) REFERENCES factor_evaluation_starts (owner_id, run_id, attempt_id, generation, id, start_id, evaluated_source_id, factor_version_id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, reservation_id) REFERENCES research_budget_reservations (owner_id, run_id, attempt_id, generation, id), \n\tCHECK (generation>0 AND manifest_sha256 ~ '^[a-f0-9]{64}$' AND journal_sha256 ~ '^[a-f0-9]{64}$'), \n\tCHECK (jsonb_typeof(manifest)='object' AND octet_length(manifest::text)<=1048576), \n\tCHECK (jsonb_typeof(journal)='object' AND octet_length(journal::text)<=2097152), \n\tCHECK (manifest_size_bytes BETWEEN 1 AND 1048576 AND peak_bytes>0 AND peak_entries BETWEEN 1 AND 256), \n\tCHECK (manifest_storage_key='factors/'||owner_id::text||'/objects/'||manifest_sha256||'.json'), \n\tCHECK (journal_key='factors/'||owner_id::text||'/objects/'||journal_sha256||'.json')\n)\n\n;\n\nCREATE TABLE factor_execution_snapshot_partitions (\n\tpublication_id UUID NOT NULL, \n\tordinal INTEGER NOT NULL, \n\tcutoff_id UUID NOT NULL, \n\tnative_publication_id UUID NOT NULL, \n\tnormalizer_admission_id UUID NOT NULL, \n\tstop_receipt_id UUID NOT NULL, \n\textraction_receipt_id UUID NOT NULL, \n\tstop_kind VARCHAR(30) NOT NULL, \n\textraction_kind VARCHAR(30) NOT NULL, \n\tbinding JSONB NOT NULL, \n\tbinding_sha256 VARCHAR(64) NOT NULL, \n\towner_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tattempt_id UUID NOT NULL, \n\tgeneration INTEGER NOT NULL, \n\tPRIMARY KEY (publication_id, ordinal), \n\tUNIQUE (normalizer_admission_id), \n\tUNIQUE (cutoff_id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, publication_id) REFERENCES factor_execution_snapshot_publications (owner_id, run_id, attempt_id, generation, id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, cutoff_id) REFERENCES factor_cutoff_executions (owner_id, run_id, attempt_id, generation, id), \n\tFOREIGN KEY(native_publication_id, normalizer_admission_id) REFERENCES factor_native_normalizer_inputs (publication_id, admission_id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, normalizer_admission_id, stop_receipt_id, stop_kind) REFERENCES research_process_receipts (owner_id, run_id, attempt_id, generation, admission_id, id, kind), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, normalizer_admission_id, extraction_receipt_id, extraction_kind) REFERENCES research_process_receipts (owner_id, run_id, attempt_id, generation, admission_id, id, kind), \n\tCHECK (generation>0 AND ordinal BETWEEN 0 AND 63 AND stop_kind='stop' AND extraction_kind='extraction'), \n\tCHECK (jsonb_typeof(binding)='object' AND octet_length(binding::text)<=65536 AND binding_sha256 ~ '^[a-f0-9]{64}$')\n)\n\n;\n\nCREATE TABLE factor_execution_snapshot_objects (\n\tid UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\tpublication_id UUID NOT NULL, \n\tobject_kind VARCHAR(32) NOT NULL, \n\tsha256 VARCHAR(64) NOT NULL, \n\tsize_bytes BIGINT NOT NULL, \n\tstorage_key VARCHAR(300) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (owner_id, id, object_kind, sha256, size_bytes, storage_key), \n\tFOREIGN KEY(owner_id, publication_id) REFERENCES factor_execution_snapshot_publications (owner_id, id), \n\tCHECK (object_kind IN ('normalized_values','assembled_rows','execution_manifest') AND sha256 ~ '^[a-f0-9]{64}$' AND size_bytes BETWEEN 1 AND 67108864), \n\tCHECK (size_bytes <= CASE WHEN object_kind='execution_manifest' THEN 1048576 ELSE 16777216 END), \n\tCHECK (storage_key='factors/'||owner_id::text||'/objects/'||sha256||CASE WHEN object_kind='normalized_values' THEN '.parquet' ELSE '.json' END)\n)\n\n;\n\nCREATE TABLE factor_execution_snapshot_outcomes (\n\tpublication_id UUID NOT NULL, \n\tmanifest_sha256 VARCHAR(64) NOT NULL, \n\tinput_sha256 VARCHAR(64) NOT NULL, \n\toutput_sha256 VARCHAR(64) NOT NULL, \n\tphysical_receipt_sha256 VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\towner_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tattempt_id UUID NOT NULL, \n\tgeneration INTEGER NOT NULL, \n\tPRIMARY KEY (publication_id), \n\tUNIQUE (owner_id, publication_id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, publication_id) REFERENCES factor_execution_snapshot_publications (owner_id, run_id, attempt_id, generation, id), \n\tCHECK (generation>0 AND manifest_sha256 ~ '^[a-f0-9]{64}$' AND input_sha256 ~ '^[a-f0-9]{64}$' AND output_sha256 ~ '^[a-f0-9]{64}$' AND physical_receipt_sha256 ~ '^[a-f0-9]{64}$')\n)\n\n;\n\nCREATE TABLE factor_execution_evaluation_outcomes (\n\tid UUID NOT NULL, \n\tevaluation_id UUID NOT NULL, \n\tgeneration_start_id UUID NOT NULL, \n\tcontroller_launch_id UUID NOT NULL, \n\tboundary_id UUID NOT NULL, \n\tsnapshot_id UUID NOT NULL, \n\tstatus VARCHAR(24) NOT NULL, \n\tsnapshot_input_sha256 VARCHAR(64) NOT NULL, \n\tsnapshot_output_sha256 VARCHAR(64) NOT NULL, \n\tsnapshot_manifest_sha256 VARCHAR(64) NOT NULL, \n\tfeedback_object_id UUID NOT NULL, \n\tfeedback_object_kind VARCHAR(40) NOT NULL, \n\tfeedback_sha256 VARCHAR(64) NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\towner_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tattempt_id UUID NOT NULL, \n\tgeneration INTEGER NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (evaluation_id), \n\tUNIQUE (snapshot_id), \n\tUNIQUE (owner_id, run_id, attempt_id, generation, id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, evaluation_id) REFERENCES factor_evaluation_starts (owner_id, run_id, attempt_id, generation, id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, boundary_id, controller_launch_id, generation_start_id) REFERENCES factor_generation_boundaries (owner_id, run_id, attempt_id, generation, id, controller_launch_id, start_id), \n\tFOREIGN KEY(owner_id, snapshot_id) REFERENCES factor_execution_snapshot_outcomes (owner_id, publication_id), \n\tFOREIGN KEY(owner_id, feedback_object_id, feedback_object_kind, feedback_sha256) REFERENCES research_objects (owner_id, id, object_kind, sha256), \n\tCHECK (generation>0 AND status='valid' AND snapshot_input_sha256 ~ '^[a-f0-9]{64}$' AND snapshot_output_sha256 ~ '^[a-f0-9]{64}$' AND snapshot_manifest_sha256 ~ '^[a-f0-9]{64}$'), \n\tCHECK (feedback_object_kind='factor_generation_feedback' AND feedback_sha256 ~ '^[a-f0-9]{64}$')\n)\n\n;\n\nCREATE TABLE factor_evaluation_result_consumers (\n\tevaluation_id UUID NOT NULL, \n\tconsumer_kind VARCHAR(32) NOT NULL, \n\tconsumer_id UUID NOT NULL, \n\towner_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tattempt_id UUID NOT NULL, \n\tgeneration INTEGER NOT NULL, \n\tPRIMARY KEY (evaluation_id), \n\tFOREIGN KEY(owner_id, run_id, attempt_id, generation, evaluation_id) REFERENCES factor_evaluation_starts (owner_id, run_id, attempt_id, generation, id), \n\tCHECK (generation>0 AND consumer_kind IN ('legacy_result','execution_result'))\n)\n\n;\n"
